import { renderOne } from '../fixtures/vendor/prompt-kit-2.0.0/src/index.js';

/**
 * Render a batch of inputs with prompt-kit 2.0.0.
 *
 * prompt-kit 2.0.0 exposes only renderOne(input), so batching belongs in the
 * caller. The input array is not mutated.
 *
 * @param {unknown[]} inputs Inputs to render, in order.
 * @returns {string[]} Rendered strings in the same order as the inputs.
 * @throws {TypeError} If inputs is not an array.
 */
export function renderBatch(inputs) {
  if (!Array.isArray(inputs)) {
    throw new TypeError('renderBatch(inputs) expects an array');
  }

  return inputs.map((input) => renderOne(input));
}
