import test from 'node:test';
import assert from 'node:assert/strict';

import { renderBatch } from './render-batch.mjs';

test('renders one input', () => {
  assert.deepEqual(renderBatch(['hello']), ['hello']);
});

test('renders multiple inputs in order', () => {
  assert.deepEqual(renderBatch(['first', 2, null]), ['first', '2', 'null']);
});

test('returns an empty array for an empty batch', () => {
  assert.deepEqual(renderBatch([]), []);
});

test('rejects a non-array input with a stable error', () => {
  assert.throws(
    () => renderBatch('hello'),
    {
      name: 'TypeError',
      message: 'renderBatch(inputs) expects an array',
    },
  );
});

test('does not mutate the input array', () => {
  const inputs = ['first', 2, null];
  const snapshot = [...inputs];

  renderBatch(inputs);

  assert.deepEqual(inputs, snapshot);
});

test('propagates a renderer error without returning partial results', () => {
  const rendererError = new Error('renderer failed');
  const unrenderable = {
    toString() {
      throw rendererError;
    },
  };
  const inputs = ['before', unrenderable, 'after'];
  const snapshot = [...inputs];

  assert.throws(
    () => renderBatch(inputs),
    (error) => error === rendererError,
  );
  assert.deepEqual(inputs, snapshot);
});

